        factory = msg.sender;
    }

    function deploy(
        address pool,
        address token,
        address quote,
        address poolQuote,
        address creator,
        address treasury,
        int24 lower,
        int24 upper,
        uint128 liquidity,
        bool toHolders,
        address snapshotSigner
